var exKg=false; // v97: chave de produto por kg (hortifruti) no produto que veio a mais
function exToggleKg(){exKg=!exKg;vibra();$('exKg').classList.toggle('on',exKg);$('exKgSt').textContent=exKg?'ON':'OFF';exUn=exKg?'KG':'UN';exProd=null;$('exSel').style.display='none';$('exRes').innerHTML='';exMarcarUn();if($('exBusca').value.trim())exBuscar();}
function exBdj(u){return u==='B500'?0.5:(u==='B600'?0.6:0);} // bandeja de 500/600 g conta como unidade
function exMarcarUn(){
  var bt=exKg?[['KG','⚖️ SOLTO / CAIXA (KG)'],['B500','BANDEJA 500G'],['B600','BANDEJA 600G']]:[['UN','UNIDADE'],['CX','CAIXA'],['KG','KG']];
  if(!bt.some(function(x){return x[0]===exUn;}))exUn=bt[0][0];
  var box=$('exUnBt');box.innerHTML='';bt.forEach(function(x){var b=document.createElement('button');b.dataset.u=x[0];b.textContent=x[1];b.classList.toggle('on',x[0]===exUn);b.onclick=function(){exUn=x[0];vibra();exMarcarUn();};box.appendChild(b);});
  $('exPesoLin').style.display=exUn==='CX'?'':'none';
  $('exQtdLb').textContent=exUn==='KG'?'Quantos kg vieram a mais?':(exBdj(exUn)?'Quantas bandejas vieram a mais?':(exUn==='CX'?'Quantas caixas vieram a mais?':'Quantos vieram a mais?'));
  $('exQtd').placeholder=exUn==='KG'?'ex.: 3,5':'ex.: 2';
}
